const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Question: 'In January 2020, did the city of Mahajanga experience more than 12 inches of rainfall?'
  const city = 'Mahajanga';
  const aoi = ee.Geometry.Point([46.3167, -15.7167]); // Mahajanga, Madagascar
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';

  // 2. Data Acquisition & Check
  const datasetId = 'UCSB-CHG/CHIRPS/DAILY';
  const precipCollection = ee.ImageCollection(datasetId)
    .filterBounds(aoi)
    .filterDate(startDate, endDate);

  const imageCount = precipCollection.size().getInfo();
  if (imageCount === 0) {
    console.log(`Evidence: No images found for ${city} in the specified period.`);
    console.log('A: No');
    return;
  }
  console.log(`Evidence: Found ${imageCount} daily precipitation images for Jan 2020.`);

  // 3. Processing
  // Sum all daily precipitation images to get total monthly precipitation.
  const totalPrecipitationImage = precipCollection.select('precipitation').sum();

  // 4. Calculation
  // Extract the total precipitation value at the point of interest.
  const scale = 5000; // CHIRPS native resolution is ~5.5km
  const precipStats = totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const totalPrecipitationMM = precipStats.get('precipitation').getInfo();

  // 5. Validation & Final Answer
  if (totalPrecipitationMM === null || totalPrecipitationMM === undefined) {
    // Check for No Valid Pixels (C2) - less likely with climate data but good practice
    const pixelCount = totalPrecipitationImage.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale
    }).get('precipitation').getInfo();

    if (pixelCount === 0) {
        console.log(`Evidence: Data exists but no valid pixels found at the location for ${city}.`);
        console.log('C2: No Valid Pixels');
        return;
    }
    console.log(`Evidence: Calculation resulted in a null value for ${city}.`);
    console.log('C3: Calculation Failure');
    return;
  }

  // Convert millimeters to inches (1 inch = 25.4 mm)
  const totalPrecipitationInches = totalPrecipitationMM / 25.4;
  const thresholdInches = 12.0;

  console.log(`Evidence: Total rainfall for ${city} in Jan 2020: ${totalPrecipitationMM.toFixed(2)} mm.`);
  console.log(`Evidence: This is equivalent to ${totalPrecipitationInches.toFixed(2)} inches.`);
  console.log(`Evidence: The threshold for comparison is ${thresholdInches} inches.`);

  if (totalPrecipitationInches > thresholdInches) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred during the analysis:', err);
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
});
